import{c as s,Q as a,j as o,m as t}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Passwordless OTP","description":"Let users log in with just their email and a one-time code.","frontmatter":{"title":"Passwordless OTP","description":"Let users log in with just their email and a one-time code."},"headers":[],"relativePath":"src/content/docs/auth/passwordless.md","filePath":"src/content/docs/auth/passwordless.md"}'),r={name:"src/content/docs/auth/passwordless.md"};function i(n,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<p>Passwordless mode lets a user log in without a password. They enter their email, receive a one-time code, and that&#39;s it. This is useful for users who find passwords inconvenient and are comfortable with email-based authentication.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>The user visits <code>/login</code> and enters their email but no password.</li><li>If the account has passwordless mode enabled, GateKeeper accepts this and sends an OTP to their email.</li><li>The user enters the OTP at <code>/login/otp</code>.</li><li>On success, the session is established.</li></ol><p>If passwordless mode is not enabled for the account, a missing password is treated as an incorrect password and the login fails.</p><h2 id="enabling-passwordless-for-a-user" tabindex="-1">Enabling passwordless for a user <a class="header-anchor" href="#enabling-passwordless-for-a-user" aria-label="Permalink to &quot;Enabling passwordless for a user&quot;">​</a></h2><p>Only admins can enable or disable passwordless mode per user. Go to <code>/admin/users/:id</code> and click <strong>Enable passwordless</strong>.</p><p>Passwordless mode is off by default for all users.</p><h2 id="security-note" tabindex="-1">Security note <a class="header-anchor" href="#security-note" aria-label="Permalink to &quot;Security note&quot;">​</a></h2><p>Passwordless login shifts trust entirely to the user&#39;s email inbox. If their email is compromised, their GateKeeper account is too. For high-security accounts, keep passwordless mode off and require both a password and the OTP.</p><p>Passkeys are a stronger alternative to passwordless OTP because they use hardware-backed keys tied to a specific device. See <a href="/auth/passkeys.html">Passkeys</a> for details.</p>',10)])])}const w=s(r,[["render",i]]);export{u as __pageData,w as default};
